using System.ComponentModel.DataAnnotations;

namespace sv_aeb79e7a2a8c4c2299b780374d2d1d29.Models;

public class RegistrationModel
{
    [Required(ErrorMessage = "Attendee name is required.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Range(0, 5, ErrorMessage = "Number of guests must be between 0 and 5.")]
    public int NumberOfGuests { get; set; }

    [Required]
    public SessionPreference PreferredSession { get; set; } = SessionPreference.Morning;

    public string? DietaryRequirements { get; set; }
}

public enum SessionPreference
{
    Morning,
    Afternoon,
    Evening
}

using sv_aeb79e7a2a8c4c2299b780374d2d1d29.Models;

namespace sv_aeb79e7a2a8c4c2299b780374d2d1d29.Services;

public class RegistrationService
{
    /// <summary>
    /// Validates the registration model against server-side rules.
    /// Returns a dictionary of field-specific errors (field name -> error message).
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidateAsync(RegistrationModel model)
    {
        var errors = new Dictionary<string, string>();

        // Simulate checking if email is already registered
        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(model.Email)] = "This email is already registered.";
        }

        return Task.FromResult(errors);
    }
}

@page "/register"
@rendermode InteractiveServer
@using sv_aeb79e7a2a8c4c2299b780374d2d1d29.Models
@using sv_aeb79e7a2a8c4c2299b780374d2d1d29.Services
@inject RegistrationService RegistrationService

<PageTitle>Event Registration</PageTitle>

<h1>Event Registration</h1>

@if (isSubmitted)
{
    <div class="alert alert-success" role="alert">
        Registration successful! Thank you, @Model.Name.
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="registration">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="name" class="form-label">Attendee Name</label>
            <InputText id="name" class="form-control" @bind-Value="Model.Name" />
            <ValidationMessage For="() => Model.Name" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(emailError))
            {
                <div class="validation-message">@emailError</div>
            }
        </div>

        <div class="mb-3">
            <label for="guests" class="form-label">Number of Guests</label>
            <InputNumber id="guests" class="form-control" @bind-Value="Model.NumberOfGuests" />
            <ValidationMessage For="() => Model.NumberOfGuests" />
        </div>

        <div class="mb-3">
            <label for="session" class="form-label">Preferred Session</label>
            <InputSelect id="session" class="form-select" @bind-Value="Model.PreferredSession">
                @foreach (var session in Enum.GetValues<SessionPreference>())
                {
                    <option value="@session">@session</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.PreferredSession" />
        </div>

        <div class="mb-3">
            <label for="dietary" class="form-label">Special Dietary Requirements</label>
            <InputTextArea id="dietary" class="form-control" @bind-Value="Model.DietaryRequirements" />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@isProcessing">
            @if (isProcessing)
            {
                <span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                <span>Registering...</span>
            }
            else
            {
                <span>Register</span>
            }
        </button>
    </EditForm>
}

@code {
    private RegistrationModel Model { get; set; } = new();
    private string? emailError;
    private bool isSubmitted;
    private bool isProcessing;

    private async Task HandleSubmit()
    {
        emailError = null;
        isProcessing = true;

        try
        {
            var serverErrors = await RegistrationService.ValidateAsync(Model);

            if (serverErrors.TryGetValue(nameof(Model.Email), out var error))
            {
                emailError = error;
                return;
            }

            if (serverErrors.Count > 0)
            {
                return;
            }

            // Registration succeeded
            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

